14	    .option('--content <dir>', 'content directory', './content')
15	    .option('--output <dir>', 'output directory', './dist')
16	    .option('--templates <dir>', 'templates directory', './templates')
17	    .action((opts: { content: string; output: string; templates: string }) => {
18	      const contentDir = path.resolve(process.cwd(), opts.content);
19	      const outputDir = path.resolve(process.cwd(), opts.output);
20	      const templatesDir = path.resolve(process.cwd(), opts.templates);
