1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdown } from './parser';
4	import { TemplateEngine } from './templateEngine';
5	import { renderIndex, renderPage } from './templates';
6	import { BuildOptions, BuildResult, Page } from './types';
7	
8	const MARKDOWN_EXTENSIONS = new Set(['.md', '.markdown']);
9	
10	/**
11	 * Recursively finds markdown files under `dir`, returning paths relative to
12	 * `dir` (using forward slashes).
13	 */
14	export function findMarkdownFiles(dir: string): string[] {
15	  const results: string[] = [];
16	
17	  function walk(current: string) {
18	    const entries = fs.readdirSync(current, { withFileTypes: true });
19	    for (const entry of entries) {
20	      const fullPath = path.join(current, entry.name);
21	      if (entry.isDirectory()) {
22	        walk(fullPath);
23	      } else if (MARKDOWN_EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
24	        results.push(path.relative(dir, fullPath).split(path.sep).join('/'));
25	      }
26	    }
27	  }
28	
29	  if (fs.existsSync(dir)) {
30	    walk(dir);
31	  }
32	
33	  return results;
34	}
35	
36	export function loadPages(contentDir: string): Page[] {
37	  const files = findMarkdownFiles(contentDir);
38	  return files.map((relativePath) => {
39	    const raw = fs.readFileSync(path.join(contentDir, relativePath), 'utf-8');
40	    return parseMarkdown(raw, relativePath);
41	  });
42	}
43	
44	function writeFile(filePath: string, contents: string) {
45	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
46	  fs.writeFileSync(filePath, contents, 'utf-8');
47	}
48	
49	const DEFAULT_STYLESHEET = `body { font-family: sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; }
50	header { margin-bottom: 2rem; }
51	.page-list { list-style: none; padding: 0; }
52	.page-list li { margin-bottom: 0.5rem; }
53	.tags { list-style: none; padding: 0; display: flex; gap: 0.5rem; }
54	.tags li { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.5rem; font-size: 0.85rem; }
55	`;
56	
57	export function buildSite(options: BuildOptions): BuildResult {
58	  const { contentDir, outputDir, templatesDir } = options;
59	
60	  if (!fs.existsSync(contentDir)) {
61	    throw new Error(`Content directory not found: ${contentDir}`);
62	  }
63	
64	  const pages = loadPages(contentDir);
65	
66	  fs.mkdirSync(outputDir, { recursive: true });
67	
68	  const engine = templatesDir && fs.existsSync(templatesDir) ? new TemplateEngine(templatesDir) : undefined;
69	
70	  for (const page of pages) {
71	    const html = engine?.renderPage(page, pages) ?? renderPage(page);
72	    writeFile(path.join(outputDir, page.outputFile), html);
73	  }
74	
75	  const indexHtml = engine?.renderIndex(pages) ?? renderIndex(pages);
76	  writeFile(path.join(outputDir, 'index.html'), indexHtml);
77	  writeFile(path.join(outputDir, 'style.css'), DEFAULT_STYLESHEET);
78	
79	  return { pages, outputDir };
80	}
