1	import * as fs from 'fs';
2	import * as path from 'path';
3	import Handlebars from 'handlebars';
4	import { renderArticleBody, renderIndexBody } from './templates';
5	import { Page } from './types';
6	
7	const DEFAULT_LAYOUT_NAME = 'default';
8	const PARTIAL_NAMES = ['header', 'nav', 'footer'];
9	
10	/**
11	 * Loads Handlebars layouts (templates/layouts/*.hbs) and partials
12	 * (templates/partials/*.hbs) from a templates directory and renders pages
13	 * through them. `header`/`nav`/`footer` partials default to empty strings
14	 * so a layout can reference them via `{{> header}}` even if the project
15	 * hasn't created that partial file yet.
16	 */
17	export class TemplateEngine {
18	  private readonly hb: typeof Handlebars;
19	  private readonly templatesDir: string;
20	  private readonly layoutCache = new Map<string, Handlebars.TemplateDelegate | undefined>();
21	
22	  constructor(templatesDir: string) {
23	    this.templatesDir = templatesDir;
24	    this.hb = Handlebars.create();
25	    for (const name of PARTIAL_NAMES) {
26	      this.hb.registerPartial(name, '');
27	    }
28	    this.loadPartials();
29	  }
30	
31	  private loadPartials(): void {
32	    const partialsDir = path.join(this.templatesDir, 'partials');
33	    if (!fs.existsSync(partialsDir)) return;
34	
35	    for (const file of fs.readdirSync(partialsDir)) {
36	      if (path.extname(file) !== '.hbs') continue;
37	      const name = path.basename(file, '.hbs');
38	      const source = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
39	      this.hb.registerPartial(name, source);
40	    }
41	  }
42	
43	  private getLayout(name: string): Handlebars.TemplateDelegate | undefined {
44	    if (this.layoutCache.has(name)) {
45	      return this.layoutCache.get(name);
46	    }
47	
48	    const layoutPath = path.join(this.templatesDir, 'layouts', `${name}.hbs`);
49	    let compiled: Handlebars.TemplateDelegate | undefined;
50	    if (fs.existsSync(layoutPath)) {
51	      const source = fs.readFileSync(layoutPath, 'utf-8');
52	      compiled = this.hb.compile(source);
53	    }
54	
55	    this.layoutCache.set(name, compiled);
56	    return compiled;
57	  }
58	
59	  /**
60	   * Renders a page through its requested layout (frontmatter `template`,
61	   * falling back to "default"). Returns undefined when neither layout
62	   * exists, so the caller can fall back to the built-in renderer.
63	   */
64	  renderPage(page: Page, pages: Page[]): string | undefined {
65	    const requested = page.template || DEFAULT_LAYOUT_NAME;
66	    const layout = this.getLayout(requested) ?? this.getLayout(DEFAULT_LAYOUT_NAME);
67	    if (!layout) return undefined;
68	
69	    return layout({
70	      page,
71	      pages,
72	      body: renderArticleBody(page),
73	      title: page.title,
74	      date: page.date,
75	      tags: page.tags,
76	    });
77	  }
78	
79	  /**
80	   * Renders the home/index page through the "index" layout, falling back
81	   * to "default". Returns undefined when neither exists.
82	   */
83	  renderIndex(pages: Page[]): string | undefined {
84	    const layout = this.getLayout('index') ?? this.getLayout(DEFAULT_LAYOUT_NAME);
85	    if (!layout) return undefined;
86	
87	    return layout({
88	      pages,
89	      body: renderIndexBody(pages),
90	      title: 'Home',
91	    });
92	  }
93	}
