1	import { Page } from './types';
2	
3	export function escapeHtml(input: string): string {
4	  return input
5	    .replace(/&/g, '&amp;')
6	    .replace(/</g, '&lt;')
7	    .replace(/>/g, '&gt;')
8	    .replace(/"/g, '&quot;')
9	    .replace(/'/g, '&#39;');
10	}
11	
12	/**
13	 * Renders a page's inner content (heading, date, tags, body HTML) without
14	 * the surrounding document shell. Used both by the built-in `renderPage`
15	 * and as the `{{{body}}}` value fed into custom Handlebars layouts.
16	 */
17	export function renderArticleBody(page: Page): string {
18	  const tagsHtml = page.tags.length
19	    ? `<ul class="tags">${page.tags.map((t) => `<li>${escapeHtml(t)}</li>`).join('')}</ul>`
20	    : '';
21	  const dateHtml = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
22	
23	  return `<h1>${escapeHtml(page.title)}</h1>
24	${dateHtml}
25	${tagsHtml}
26	${page.html}`;
27	}
28	
29	export function renderPage(page: Page): string {
30	  return `<!DOCTYPE html>
31	<html lang="en">
32	<head>
33	<meta charset="UTF-8">
34	<meta name="viewport" content="width=device-width, initial-scale=1.0">
35	<title>${escapeHtml(page.title)}</title>
36	<link rel="stylesheet" href="style.css">
37	</head>
38	<body>
39	<header>
40	<a href="index.html">&larr; Home</a>
41	</header>
42	<article>
43	${renderArticleBody(page)}
44	</article>
45	</body>
46	</html>
47	`;
48	}
49	
50	/**
51	 * Renders the home page's page-listing markup, without the surrounding
52	 * document shell. Used both by the built-in `renderIndex` and as the
53	 * `{{{body}}}` value fed into a custom "index" Handlebars layout.
54	 */
55	export function renderIndexBody(pages: Page[]): string {
56	  const sorted = [...pages].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
57	  const items = sorted
58	    .map((page) => {
59	      const dateHtml = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
60	      return `<li><a href="${escapeHtml(page.outputFile)}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
61	    })
62	    .join('\n');
63	
64	  return `<ul class="page-list">
65	${items}
66	</ul>`;
67	}
68	
69	export function renderIndex(pages: Page[]): string {
70	  return `<!DOCTYPE html>
71	<html lang="en">
72	<head>
73	<meta charset="UTF-8">
74	<meta name="viewport" content="width=device-width, initial-scale=1.0">
75	<title>Home</title>
76	<link rel="stylesheet" href="style.css">
77	</head>
78	<body>
79	<header>
80	<h1>Home</h1>
81	</header>
82	${renderIndexBody(pages)}
83	</body>
84	</html>
85	`;
86	}
